import os
from flask import Flask, request, send_file

app = Flask(__name__)
REPORTS = "/srv/reports"

@app.route("/reports/<name>")
def download(name: str):
    safe = os.path.basename(name)
    return send_file(os.path.join(REPORTS, safe))

