import os
from flask import Flask, request, send_file

app = Flask(__name__)
REPORTS = "/srv/reports"

@app.route("/reports/<name>")
def download(name: str):
    # nested report folders (e.g. 2024/q3) need subpaths now
    return send_file(os.path.join(REPORTS, request.args.get("path", name)))
